#!/usr/bin/env python3
"""Patches the Android project generated by `flutter create` in CI:
permissions, app label, min SDK, release signing, MainActivity method channel."""
import os, re, sys, glob

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
android = os.path.join(root, "android")

# ---------- AndroidManifest ----------
mf = os.path.join(android, "app", "src", "main", "AndroidManifest.xml")
m = open(mf, encoding="utf-8").read()
perms = """
    <uses-permission android:name="android.permission.INTERNET" />
    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />
    <uses-permission android:name="android.permission.ACCESS_WIFI_STATE" />
    <uses-permission android:name="android.permission.CAMERA" />
    <uses-permission android:name="android.permission.REQUEST_INSTALL_PACKAGES" />
    <uses-feature android:name="android.hardware.camera" android:required="false" />
"""
if "REQUEST_INSTALL_PACKAGES" not in m:
    m = m.replace("<application", perms + "    <application", 1)
m = re.sub(r'android:label="[^"]*"', 'android:label="Kalori Hesaplayıcı"', m, count=1)
if 'android:usesCleartextTraffic' not in m:
    m = m.replace("<application", '<application\n        android:usesCleartextTraffic="true"', 1)
# FileProvider for APK install (open_filex ships its own provider; nothing to add)
open(mf, "w", encoding="utf-8").write(m)

# ---------- build.gradle(.kts) ----------
kts = os.path.join(android, "app", "build.gradle.kts")
groovy = os.path.join(android, "app", "build.gradle")
ks_path = (os.environ.get("KEYSTORE_PATH") or os.path.join(root, "android-signing", "release.jks")).replace("\\", "/")
ks_pass = os.environ.get("KEYSTORE_PASSWORD") or "kalori2026"
ks_alias = os.environ.get("KEY_ALIAS") or "kalori"

if os.path.exists(kts):
    g = open(kts, encoding="utf-8").read()
    g = re.sub(r'minSdk\s*=\s*[^\n]+', 'minSdk = 23', g)
    g = re.sub(r'applicationId\s*=\s*"[^"]+"', 'applicationId = "com.departures.kalori"', g)
    signing = f'''
    signingConfigs {{
        create("release") {{
            storeFile = file("{ks_path}")
            storePassword = "{ks_pass}"
            keyAlias = "{ks_alias}"
            keyPassword = "{ks_pass}"
        }}
    }}
'''
    if 'create("release")' not in g:
        g = g.replace("    buildTypes {", signing + "    buildTypes {", 1)
    g = re.sub(r'signingConfig\s*=\s*signingConfigs\.getByName\("debug"\)',
               'signingConfig = signingConfigs.getByName("release")', g)
    open(kts, "w", encoding="utf-8").write(g)
    print("patched build.gradle.kts")
elif os.path.exists(groovy):
    g = open(groovy, encoding="utf-8").read()
    g = re.sub(r'minSdk(Version)?\s*=?\s*[^\n]+', 'minSdk = 23', g)
    g = re.sub(r'applicationId\s*=?\s*"[^"]+"', 'applicationId = "com.departures.kalori"', g)
    signing = f'''
    signingConfigs {{
        release {{
            storeFile file("{ks_path}")
            storePassword "{ks_pass}"
            keyAlias "{ks_alias}"
            keyPassword "{ks_pass}"
        }}
    }}
'''
    if "signingConfigs {" not in g:
        g = g.replace("    buildTypes {", signing + "    buildTypes {", 1)
    g = re.sub(r'signingConfig\s+signingConfigs\.debug', 'signingConfig signingConfigs.release', g)
    open(groovy, "w", encoding="utf-8").write(g)
    print("patched build.gradle")
else:
    sys.exit("no app build.gradle found")

# ---------- MainActivity (method channel: minimize) ----------
acts = glob.glob(os.path.join(android, "app", "src", "main", "kotlin", "**", "MainActivity.kt"), recursive=True)
if not acts:
    sys.exit("MainActivity.kt not found")
act = acts[0]
pkg = re.search(r'package\s+([\w.]+)', open(act, encoding="utf-8").read()).group(1)
open(act, "w", encoding="utf-8").write(f'''package {pkg}

import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel

class MainActivity : FlutterActivity() {{
    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {{
        super.configureFlutterEngine(flutterEngine)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "kalori/window")
            .setMethodCallHandler {{ call, result ->
                when (call.method) {{
                    "minimize" -> {{ moveTaskToBack(true); result.success(null) }}
                    else -> result.notImplemented()
                }}
            }}
    }}
}}
''')
print("patched", act)

# ---------- remove generated widget test (not maintained) ----------
t = os.path.join(root, "test", "widget_test.dart")
if os.path.exists(t):
    os.remove(t)
print("done")
